#!/usr/bin/env python3
"""Compare Prometheus output with reconstructed calls, including exact buckets."""
import collections,json,math,re,sys

def labels(text):
    # Exposition is generated by the Prometheus client. Decode its three escapes.
    result={}
    for key,value in re.findall(r'(\w+)="((?:\\.|[^"\\])*)"',text or ''):
        result[key]=re.sub(r'\\([\\"n])',lambda m:'\n' if m[1]=='n' else m[1],value)
    return result

def check(calls_path,metrics_path):
    calls=[json.loads(line) for line in open(calls_path) if line.strip()]
    assert calls,'no observed calls'
    samples={}
    for line in open(metrics_path):
        if line.startswith('#') or not line.strip():continue
        m=re.fullmatch(r'(\w+)(?:\{(.*)\})? ([^ ]+)(?: \d+)?\n?',line)
        assert m,line
        name,raw,value=m.groups();lab=labels(raw)
        assert lab['service']=='phase6-echo' and lab['namespace']=='test' and lab['pod']=='fixture',lab
        k=(name,tuple(sorted(lab.items())))
        assert k not in samples,'duplicate series';samples[k]=float(value)
    groups=collections.defaultdict(list)
    for c in calls:groups[(c['method'],'server' if c['request_direction']=='read' else 'client',str(c['status']))].append(c)
    for (method,role,status),group in groups.items():
        base=dict(service='phase6-echo',namespace='test',pod='fixture',method=method,role=role,grpc_status=status)
        def get(name,**extra):return samples[('axon_'+name,tuple(sorted((base|extra).items())))]
        assert get('grpc_requests_total')==len(group)
        timed=[c['latency_ns']/1e9 for c in group if c['timing_valid']]
        assert get('grpc_request_duration_seconds_count')==len(timed)
        assert math.isclose(get('grpc_request_duration_seconds_sum'),sum(timed),rel_tol=1e-9,abs_tol=1e-12)
        assert get('grpc_requests_without_timing_total')==len(group)-len(timed)
        for side in ('request','response'):assert get('grpc_'+side+'_bytes_total')==sum(c[side+'_bytes'] for c in group)
        for k,value in samples.items():
            name,items=k;lab=dict(items)
            if name=='axon_grpc_request_duration_seconds_bucket' and all(lab.get(k)==v for k,v in base.items()):
                assert value==sum(s<=float(lab['le']) for s in timed),(lab,value)
    observed=sum(value for (name,_),value in samples.items() if name=='axon_grpc_requests_total')
    assert observed==len(calls),(observed,len(calls))
    assert {c['request_direction'] for c in calls}=={'read','write'}
    assert any(c['status']!=0 for c in calls),'error fixture absent'
    assert all(v==0 for (name,_),v in samples.items() if name=='axon_metrics_dropped_observations_total')
    print(f'Phase6 verified: {len(calls)} endpoint records, {len(groups)} metric groups; exact status/count/bytes/latency buckets')
if __name__=='__main__':check(*sys.argv[1:])
